# Responsive versions keep each original file intact.
image_meta={}
for original in sorted((ROOT/'web').rglob('*')):
    if original.suffix.lower() not in ['.png','.jpg','.jpeg','.webp']:continue
    rel='/'+original.relative_to(ROOT).as_posix()
    with Image.open(original) as im:
        im=im.convert('RGB');variants=[]
        for w in [480,960,1440]:
            if w>im.width and variants:continue
            out=im.copy();out.thumbnail((w,w*4));target='assets/images/'+original.relative_to(ROOT/'web').as_posix().replace('/','-').rsplit('.',1)[0]+f'-{w}.webp';(ROOT/target).parent.mkdir(parents=True,exist_ok=True);out.save(ROOT/target,'WEBP',quality=82);variants.append(('/'+target,out.width))
        image_meta[rel]=(im.width,im.height,variants)
def image(src,alt,cls='',eager=False):
    w,h,variants=image_meta[src];srcset=', '.join(f'{v} {width}w' for v,width in variants)
    return f'<img class="{cls}" src="{variants[-1 if eager else 0][0]}" srcset="{srcset}" sizes="{'(max-width:800px) calc(100vw - 40px), 1100px' if eager else '(max-width:800px) calc(100vw - 40px), (max-width:1100px) 45vw, 410px'}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async" alt="{e(alt)}">'
